mapper.select:
select s.id,s.name,s.no,s.gender,s.clazz_id,c.name as clazz_name,s.phone,s.degree,s.violation_count,s.violation_score,s.update_time
from student s left join clazz c on s.clazz_id = c.id


    s.name like concat('%',#{name},'%')


    AND s.clazz_id = #{clazzId}


    AND s.degree = #{degree}


order by s.update_time desc

select s.id,s.name,s.no,s.gender,s.clazz_id,c.name as clazz_name,s.phone,s.degree,s.address,s.id_card,s.is_college,s.graduation_date,s.violation_count,s.violation_score,s.update_time,s.create_time
